import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"🤫 Suppressions & Pragmas Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/suppressions.md","filePath":"guide/suppressions.md"}'),n={name:"guide/suppressions.md"};function o(l,s,r,p,d,h){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="🤫-suppressions-pragmas-guide" tabindex="-1">🤫 Suppressions &amp; Pragmas Guide <a class="header-anchor" href="#🤫-suppressions-pragmas-guide" aria-label="Permalink to &quot;🤫 Suppressions &amp; Pragmas Guide&quot;">​</a></h1><p>In Clean ABAP development, static analysis rules guide quality and readability. However, in certain scenarios—such as interfacing with external legacy APIs or performance-critical micro-optimizations—deviating from a rule is intentional and necessary.</p><p>Skylint supports full <strong>statement-level suppression</strong> using standard ABAP pseudo-comments and modern compiler pragmas, fully compliant with <strong>SAP ATC and Code Pal standards</strong>.</p><hr><h2 id="🎯-dual-match-compatibility-tag-ci-tag" tabindex="-1">🎯 Dual-Match Compatibility (<code>TAG</code> &amp; <code>CI_TAG</code>) <a class="header-anchor" href="#🎯-dual-match-compatibility-tag-ci-tag" aria-label="Permalink to &quot;🎯 Dual-Match Compatibility (\`TAG\` &amp; \`CI_TAG\`)&quot;">​</a></h2><p>In adherence to SAP&#39;s ATC framework design (as seen in SAP Code Pal for ABAP Cloud), Skylint check rules support <strong>both</strong> modern concise tags and traditional SAP <code>CI_</code> prefixed tags:</p><ul><li><strong>Concise Format:</strong> <code>&quot;#EC &lt;TAG&gt;&quot;</code> or <code>##&lt;TAG&gt;</code></li><li><strong>Official SAP ATC Format:</strong> <code>&quot;#EC CI_&lt;TAG&gt;&quot;</code> or <code>##CI_&lt;TAG&gt;</code></li></ul><p>Both formats are 100% equivalent and recognized by Skylint.</p><hr><h2 id="_1-using-pseudo-comments-ec" tabindex="-1">1. Using Pseudo-Comments (<code>&quot;#EC ...&quot;</code>) <a class="header-anchor" href="#_1-using-pseudo-comments-ec" aria-label="Permalink to &quot;1. Using Pseudo-Comments (\`&quot;#EC ...&quot;\`)&quot;">​</a></h2><p>Place the pseudo-comment at the end of the flagged ABAP statement (after the period or colon):</p><div class="language-abap vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">abap</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&quot; Flagged by rule &#39;prefer-lines&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESCRIBE TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lt_customers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LINES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lv_count. </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&quot;#EC LINES</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&quot; Traditional SAP ATC prefix is also recognized</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESCRIBE TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lt_customers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LINES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lv_count. </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&quot;#EC CI_LINES</span></span></code></pre></div><h3 id="multiple-pseudo-comments-on-one-statement" tabindex="-1">Multiple Pseudo-Comments on One Statement <a class="header-anchor" href="#multiple-pseudo-comments-on-one-statement" aria-label="Permalink to &quot;Multiple Pseudo-Comments on One Statement&quot;">​</a></h3><p>If a single statement triggers multiple checks, you can combine pseudo-comments separated by spaces or commas:</p><div class="language-abap vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">abap</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESCRIBE TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lt_data </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LINES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lv_count. </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&quot;#EC LINES, NO_DESCRIBE</span></span></code></pre></div><hr><h2 id="_2-using-modern-pragmas" tabindex="-1">2. Using Modern Pragmas (<code>##...</code>) <a class="header-anchor" href="#_2-using-modern-pragmas" aria-label="Permalink to &quot;2. Using Modern Pragmas (\`##...\`)&quot;">​</a></h2><p>Modern ABAP introduces pragmas (<code>##</code>) which are recognized directly by the ABAP compiler and placed before the statement&#39;s terminating period <code>.</code>:</p><div class="language-abap vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">abap</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&quot; Flagged by rule &#39;no-call-method&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CALL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> METHOD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lo_service-&gt;process_item </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">##CALL_METH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&quot; Using the CI_ prefix</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CALL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> METHOD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lo_service-&gt;process_item </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">##CI_CALL_METH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span></code></pre></div><h3 id="advantages-of-pragmas-over-pseudo-comments" tabindex="-1">Advantages of Pragmas over Pseudo-Comments <a class="header-anchor" href="#advantages-of-pragmas-over-pseudo-comments" aria-label="Permalink to &quot;Advantages of Pragmas over Pseudo-Comments&quot;">​</a></h3><ol><li><strong>Compiler Validated:</strong> The ABAP compiler verifies pragma syntax during compilation.</li><li><strong>Refactoring Safe:</strong> Moving or reformatting lines preserves pragmas more reliably than trailing text comments.</li><li><strong>Clean ABAP Recommended:</strong> Clean ABAP guidelines favor compiler pragmas (<code>##</code>) over legacy pseudo-comments (<code>&quot;#EC</code>).</li></ol><hr><h2 id="_3-how-the-base-engine-evaluates-suppressions" tabindex="-1">3. How the Base Engine Evaluates Suppressions <a class="header-anchor" href="#_3-how-the-base-engine-evaluates-suppressions" aria-label="Permalink to &quot;3. How the Base Engine Evaluates Suppressions&quot;">​</a></h2><p>Every Skylint check inherits from <code>zcl_skylint_check_base</code>. When a statement or token is reported:</p><ol><li>Skylint inspects the statement&#39;s associated <code>pseudo_comments</code> table provided by the ATC framework (<code>if_ci_atc_source_code_provider=&gt;ty_statement</code>).</li><li>It evaluates whether either the registered tag (e.g. <code>LINES</code>) or its <code>CI_</code> prefixed counterpart (e.g. <code>CI_LINES</code>) is attached.</li><li>If a match is found, the finding is suppressed automatically, preventing false alarms in your ATC run and CI/CD pipelines.</li></ol><hr><h2 id="💡-best-practices-for-suppressions" tabindex="-1">💡 Best Practices for Suppressions <a class="header-anchor" href="#💡-best-practices-for-suppressions" aria-label="Permalink to &quot;💡 Best Practices for Suppressions&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Clean ABAP Guideline: Fix First, Suppress Only with Justification</p><ol><li><strong>Always prefer fixing over suppressing:</strong> If an automated QuickFix is available (<kbd>Ctrl</kbd> + <kbd>1</kbd>), apply it rather than hiding the finding.</li><li><strong>Document the rationale:</strong> Whenever you add a pseudo-comment or pragma, accompany it with a brief explanatory comment explaining <em>why</em> the rule was bypassed:<div class="language-abap vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">abap</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&quot; External RFC interface requires classical EXPORTING syntax</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lo_proxy-&gt;call_legacy_endpoint( </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXPORTING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iv_data </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lv_payload ) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">##CI_NO_EXPORTING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span></code></pre></div></li><li><strong>Do not blanket-suppress:</strong> Suppress only the exact offending statement. Avoid wide-ranging suppression where possible.</li></ol></div><hr><h2 id="🔍-finding-rule-suppression-codes" tabindex="-1">🔍 Finding Rule Suppression Codes <a class="header-anchor" href="#🔍-finding-rule-suppression-codes" aria-label="Permalink to &quot;🔍 Finding Rule Suppression Codes&quot;">​</a></h2><p>Every rule in Skylint defines its specific suppression code. You can find the exact pseudo-comment or pragma code for any check:</p><ul><li>In the <a href="/rules/">Rules Catalog</a> under each rule&#39;s documentation page.</li><li>In Eclipse ADT: open the finding in the <strong>ATC Result View</strong> to see the suggested suppression code in the finding details.</li></ul>`,32)])])}const u=e(n,[["render",o]]);export{g as __pageData,u as default};
